python3 -c "
import json
with open('/app/resources/treasury_bulletin_2011_12.json') as f:
    data = json.load(f)

# Let's see the structure
def find_keys(obj, target='judicial', path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if target in k.lower():
                results.append((new_path, type(v).__name__))
            results.extend(find_keys(v, target, new_path))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_keys(item, target, f'{path}[{i}]'))
    return results

results = find_keys(data, 'judicial')
for r in results[:20]:
    print(r)
"
